<template><AppLayout><div v-if="loading" class="loading">正在加载分析报告...</div><template v-else-if="report"><header class="report-head"><div><button @click="$router.push('/analysis')">← 返回岗位匹配</button><span>分析报告 #{{ report.id }}</span><h1>{{ report.position }}</h1><p>{{ report.company||'未填写公司' }} · 使用「{{ report.resume_title }}」分析</p></div><div class="score" :style="{'--score':`${result.score*3.6}deg`} "><div><strong>{{ result.score }}</strong><small>匹配分</small></div></div></header>
<section class="summary"><span>AI 结论</span><p>{{ result.summary }}</p><div><small>分析耗时 {{ (report.duration_ms/1000).toFixed(1) }}s</small><small>{{ formatDate(report.created_at) }}</small></div></section>
<div class="metrics"><article><span class="icon purple">✓</span><div><small>匹配优势</small><strong>{{ result.strengths.length }} 项</strong></div></article><article><span class="icon orange">!</span><div><small>能力差距</small><strong>{{ result.gaps.length }} 项</strong></div></article><article><span class="icon blue">#</span><div><small>缺失关键词</small><strong>{{ result.keywords.missing.length }} 个</strong></div></article></div>
<div class="report-grid"><main><ReportSection index="01" title="核心优势"><ul class="strengths"><li v-for="item in result.strengths" :key="item"><span>✓</span>{{ item }}</li></ul></ReportSection><ReportSection index="02" title="能力差距与行动建议"><div class="gaps"><article v-for="gap in result.gaps" :key="gap.keyword"><div><b>{{ gap.keyword }}</b><em :class="gap.importance">{{ labels[gap.importance] }}</em></div><p>{{ gap.advice }}</p></article></div></ReportSection><ReportSection index="03" title="简历改写建议"><div class="suggestions"><article v-for="(item,i) in result.suggestions" :key="i" :class="{applied:isApplied(i)}"><header><span>{{ item.section }}</span><small>{{ item.reason }}</small></header><div v-if="item.original" class="original"><b>原内容</b><p>{{ item.original }}</p></div><div class="optimized"><b>建议表达</b><p>{{ item.optimized }}</p></div><footer><span v-if="isApplied(i)">✓ 已采纳到简历</span><el-button v-else type="primary" plain @click="openApply(i)">采纳此建议</el-button></footer></article></div></ReportSection></main>
<aside><section class="keyword-card"><h3>关键词覆盖</h3><div><small>已匹配</small><p><span v-for="word in result.keywords.matched" :key="word" class="matched">{{ word }}</span></p></div><div><small>建议补充</small><p><span v-for="word in result.keywords.missing" :key="word" class="missing">{{ word }}</span></p></div></section><section class="question-card"><span>面试准备</span><h3>建议重点准备的问题</h3><ol><li v-for="q in result.interviewQuestions" :key="q">{{ q }}</li></ol></section><el-button class="new-analysis" size="large" @click="$router.push('/analysis')">分析另一个岗位</el-button></aside></div><el-dialog v-model="applyVisible" title="采纳优化建议" width="520px"><p class="dialog-tip">选择要替换的简历模块。系统会先自动保存当前版本，你可以随时恢复。</p><el-select v-model="targetPath" placeholder="请选择应用位置" style="width:100%"><el-option v-for="option in targetOptions" :key="option.value" :label="option.label" :value="option.value"/></el-select><template #footer><el-button @click="applyVisible=false">取消</el-button><el-button type="primary" :loading="applying" :disabled="!targetPath" @click="confirmApply">保存版本并采纳</el-button></template></el-dialog></template></AppLayout></template>
<script setup>
import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import AppLayout from'@/layouts/AppLayout.vue';import ReportSection from'@/components/analysis/ReportSection.vue';import{applySuggestion,getAnalysis}from'@/api/jobs';import{getResume}from'@/api/resumes';const route=useRoute(),loading=ref(true),report=ref(null),resume=ref(null),result=ref({strengths:[],gaps:[],keywords:{matched:[],missing:[]},suggestions:[],interviewQuestions:[]}),applied=ref([]),applyVisible=ref(false),applying=ref(false),selectedIndex=ref(null),targetPath=ref('');const labels={high:'高优先级',medium:'中优先级',low:'低优先级'};onMounted(async()=>{try{const response=(await getAnalysis(route.params.id)).data.data;report.value=response.analysis;result.value=report.value.result;applied.value=response.appliedSuggestions||[];resume.value=(await getResume(report.value.resume_id)).data.data.resume}catch(e){ElMessage.error(e.response?.data?.message||'报告加载失败')}finally{loading.value=false}});const targetOptions=computed(()=>{const content=resume.value?.content;if(!content)return[];return[{label:'个人简介',value:'basics.summary'},...(content.education||[]).map((x,i)=>({label:`教育经历 · ${x.school||`第 ${i+1} 项`}`,value:`education.${i}.description`})),...(content.experience||[]).map((x,i)=>({label:`工作经历 · ${x.company||`第 ${i+1} 项`}`,value:`experience.${i}.description`})),...(content.projects||[]).map((x,i)=>({label:`项目经历 · ${x.name||`第 ${i+1} 项`}`,value:`projects.${i}.description`}))]});const isApplied=index=>applied.value.some(x=>x.suggestion_index===index);const openApply=index=>{selectedIndex.value=index;targetPath.value='';applyVisible.value=true};const confirmApply=async()=>{applying.value=true;try{const response=await applySuggestion(route.params.id,{suggestionIndex:selectedIndex.value,targetPath:targetPath.value});resume.value=response.data.data.resume;applied.value.push({suggestion_index:selectedIndex.value,target_path:targetPath.value});applyVisible.value=false;ElMessage.success('建议已采纳，原简历已自动备份')}catch(e){ElMessage.error(e.response?.data?.message||'采纳失败')}finally{applying.value=false}};const formatDate=v=>new Date(v.replace(' ','T')+'Z').toLocaleString('zh-CN')
</script>
<style scoped>.loading{display:grid;place-items:center;height:70vh;color:#8b91a0}.report-head{display:flex;justify-content:space-between;align-items:center;padding:5px 5px 26px}.report-head button{padding:0;border:0;background:none;color:#6d4aff;cursor:pointer}.report-head span{margin-left:14px;color:#969ba7;font-size:12px}.report-head h1{margin-top:8px;font-size:32px;font-weight:760}.report-head p{color:#7f8592}.score{width:114px;height:114px;padding:8px;border-radius:50%;background:conic-gradient(#6d4aff var(--score),#e9e8f1 0)}.score>div{height:100%;display:grid;place-content:center;border-radius:50%;background:#f6f7fb;text-align:center}.score strong{font-size:34px;font-weight:780}.score small{color:#878d9a}.summary{padding:24px 28px;border-radius:17px;background:#171923;color:#fff}.summary>span{color:#9e8eff;font-size:11px;font-weight:800;letter-spacing:1.5px}.summary>p{margin:8px 0 13px;font-size:17px;line-height:1.75}.summary>div{display:flex;gap:18px;color:#8e95a4}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:20px 0}.metrics article{display:flex;align-items:center;gap:13px;padding:18px;background:#fff;border:1px solid #e6e8ee;border-radius:15px}.icon{display:grid;place-items:center;width:40px;height:40px;border-radius:11px;font-weight:800}.purple{background:#eeeaff;color:#6d4aff}.orange{background:#fff1e8;color:#d76a28}.blue{background:#e9f3ff;color:#2777c7}.metrics article div{display:flex;flex-direction:column}.metrics small{color:#8e94a1}.metrics strong{font-size:18px;font-weight:700}.report-grid{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:20px}.strengths{display:grid;grid-template-columns:1fr 1fr;gap:10px;list-style:none;padding:0}.strengths li{padding:13px;background:#f7f8fb;border-radius:10px}.strengths span{margin-right:9px;color:#38a06c}.gaps article{padding:15px 0;border-top:1px solid #eee}.gaps article:first-child{border:0}.gaps article div{display:flex;align-items:center;gap:9px}.gaps b{font-weight:700}.gaps em{padding:2px 8px;border-radius:9px;font-size:11px;font-style:normal}.gaps .high{background:#ffebea;color:#c33}.gaps .medium{background:#fff2dc;color:#a76600}.gaps .low{background:#edf2fa;color:#54708e}.gaps p{margin-top:5px;color:#6f7582}.suggestions>article{margin-top:14px;border:1px solid #e6e7ed;border-radius:12px;overflow:hidden}.suggestions header{display:flex;justify-content:space-between;padding:11px 14px;background:#f7f7fa}.suggestions header span{font-weight:700}.suggestions header small{color:#858b98}.suggestions .original,.suggestions .optimized{padding:13px 15px}.suggestions b{color:#999;font-size:11px}.suggestions p{white-space:pre-line}.suggestions .optimized{background:#f8f6ff;border-top:1px solid #e8e2ff}.suggestions .optimized b{color:#6d4aff}.keyword-card,.question-card{padding:21px;background:#fff;border:1px solid #e5e7ed;border-radius:17px}.keyword-card h3,.question-card h3{font-size:17px;font-weight:700}.keyword-card>div{margin-top:18px}.keyword-card small{color:#858b98}.keyword-card p{display:flex;flex-wrap:wrap;gap:7px;margin-top:7px}.keyword-card p span{padding:4px 9px;border-radius:8px;font-size:12px}.matched{background:#eaf8f0;color:#287a4e}.missing{background:#fff0eb;color:#b95332}.question-card{margin-top:16px;background:#f2efff;border-color:#e1d9ff}.question-card>span{color:#6d4aff;font-size:11px;font-weight:750}.question-card ol{display:grid;gap:12px;margin-top:14px;padding-left:20px;color:#555b68}.new-analysis{width:100%;margin-top:16px}@media(max-width:1000px){.report-grid{grid-template-columns:1fr}.report-grid>aside{display:grid;grid-template-columns:1fr 1fr;gap:16px}.question-card{margin-top:0}}@media(max-width:700px){.metrics,.strengths,.report-grid>aside{grid-template-columns:1fr}.report-head{align-items:flex-start}.score{width:90px;height:90px}.score strong{font-size:27px}}
.suggestions article.applied{border-color:#bce4cc}.suggestions footer{display:flex;justify-content:flex-end;padding:10px 14px;border-top:1px solid #ececf2}.suggestions footer span{color:#278454;font-weight:650}.dialog-tip{margin:-5px 0 18px;color:#747b88;line-height:1.7}</style>
